import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { MatrixService } from "modules/matrix-client/services/matrix-service";
import { useEffect, useState } from "react";
import { ActivityIndicator, Image, StyleSheet } from "react-native";
import Toast from "react-native-toast-message";
import {
  Button,
  GoBackHeader,
  RadioButton,
  ScreenLayout,
} from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const Encryption: React.FC<
  NativeStackScreenProps<Routes, "encryption">
> = ({ navigation }) => {
  const [allowedKeyStorage, setAllowedKeyStorage] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isTogglingBackup, setIsTogglingBackup] = useState<boolean>(false);

  useEffect(() => {
    const checkBackupStatus = async () => {
      try {
        setIsLoading(true);
        const backupExists = await MatrixService.backupExists();
        setAllowedKeyStorage(backupExists);
      } catch (error) {
        console.error("Failed to check backup status:", error);
        Toast.show({
          text1: "Failed to check backup status",
          type: "error",
        });
      } finally {
        setIsLoading(false);
      }
    };

    checkBackupStatus();
  }, []);

  const handleToggleKeyStorage = async () => {
    try {
      setIsTogglingBackup(true);

      if (allowedKeyStorage) {
        // await MatrixService.disableRecovery();
        setAllowedKeyStorage(false);
        Toast.show({
          text1: "Key storage disabled",
          text2: "Your keys will no longer be backed up to the server",
          type: "info",
        });
        return;
      }

      // await MatrixService.enableBackups();
      setAllowedKeyStorage(true);
      Toast.show({
        text1: "Key storage enabled",
        text2: "Your keys are now backed up securely to the server",
        type: "success",
      });
    } catch (error) {
      console.error("Failed to toggle key storage:", error);
      Toast.show({
        text1: "Failed to toggle key storage",
        text2: error instanceof Error ? error.message : "Unknown error",
        type: "error",
      });
    } finally {
      setIsTogglingBackup(false);
    }
  };

  return (
    <ScreenLayout>
      <Block flex={1} align="center" gap={40}>
        <GoBackHeader title="Encryption" margins={0} />
        <Block gap={8} width="100%">
          <Text size={TextSize.tiny} color={Colors.white50} paddings={[0, 12]}>
            Key storage
          </Text>
          {isLoading ? (
            <Block paddings={[20, 12]} align="center">
              <ActivityIndicator size="small" color={Colors.primary} />
            </Block>
          ) : (
            <RadioButton
              disabled={isTogglingBackup}
              checked={allowedKeyStorage}
              onToggle={handleToggleKeyStorage}
              label="Allow key storage"
            />
          )}
          <Block flexDirection="row" gap={12}>
            <Image source={require("assets/icons/info.png")} />
            <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
              Store your cryptographic identity and message keys securely on the
              server. This will allow you to view your message history on any
              new devices.
            </Text>
          </Block>
        </Block>
        <Block width="100%" gap={8}>
          <Button.Wrapper
            style={styles.button}
            onPress={() => navigation.navigate("setUpRecoveryKey")}
          >
            <Block
              paddings={[20, 12]}
              flexDirection="row"
              align="center"
              justify="space-between"
              border={{
                borderRadius: 16,
              }}
              background={Colors.white5}
            >
              <Text size={TextSize.base}>
                {allowedKeyStorage ? "Change recovery key" : "Set up recovery"}
              </Text>
              <Image
                source={require("assets/icons/caret-left.png")}
                style={styles.caret}
              />
            </Block>
          </Button.Wrapper>
          <Block flexDirection="row" gap={12}>
            <Image source={require("assets/icons/info.png")} />
            <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
              Get access to your encrypted messages if you lose all your devices
              or are signed out of Cloak everywhere.
            </Text>
          </Block>
        </Block>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  button: {
    width: "100%",
  },
  caret: {
    transform: [{ rotate: "180deg" }],
    width: 24,
    height: 24,
    marginLeft: "auto",
  },
});

