   113→  /** Attempt to restore session from stored credentials */
   114→  public static restoreSession = async (): Promise<boolean> => {
   115→    try {
   116→      const credentials = MatrixStorage.getLoginCredentials();
   117→
   118→      if (!credentials) return false;
   119→
   120→      await this.initialize(credentials.baseUrl);
   121→
   122→      if (!this.instance) throw new Error("Failed to initialize client");
   123→
   124→      // Create client with stored credentials
   125→      await this.instance.restoreSession({
   126→        accessToken: credentials.accessToken,
   127→        refreshToken: credentials.refreshToken,
   128→        userId: credentials.userId,
   129→        deviceId: credentials.deviceId,
   130→        homeserverUrl: credentials.baseUrl,
   131→        oidcData: undefined,
   132→        slidingSyncVersion: SlidingSyncVersion.Native,
   133→      });
   134→
   135→      // Verify the session is valid by making a server request
   136→      try {
   137→        this.profile = await this.instance.getProfile(credentials.userId);
   138→      } catch (error) {
   139→        console.warn("Session validation failed:", error);
   140→        throw new Error("Session is invalid or expired");
   141→      }
   142→
   143→      this.syncService = await this.instance.syncService().finish();
   144→
   145→      if (!this.syncService) {
   146→        throw new Error("Failed to initialize sync service");
   147→      }
   148→
   149→      await this.syncService.start();
   150→
   151→      // Update atoms so providers can react to the initialized service
   152→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   153→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   154→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   155→
   156→      return true;
   157→    } catch (error) {
   158→      console.warn("Failed to restore session:", error);
   159→
   160→      // Clear both credentials and crypto store to ensure clean state
   161→      MatrixStorage.clearLoginCredentials();
   162→      await this.clearCryptoStore();
   163→
   164→      // Reset the instance so it can be recreated fresh
   165→      this.instance = null;
   166→      this.syncService = null;
   167→
   168→      // Clear atoms
   169→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   170→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   171→
   172→      return false;
   173→    }
   174→  };
