   176→  /** Call this after logging in to create a new client instance with the provided account.  */
   177→  public static setup = async (params: Session) => {
   178→    // Clear any existing crypto store to prevent device ID mismatches
   179→    await this.clearCryptoStore();
   180→
   181→    // Stop and clear existing instances
   182→    if (this.syncService) await this.syncService.stop();
   183→    this.instance = null;
   184→    this.syncService = null;
   185→
   186→    // Save credentials for future auto-login
   187→    MatrixStorage.saveLoginCredentials({
   188→      accessToken: params.accessToken,
   189→      refreshToken: params.refreshToken,
   190→      userId: params.userId,
   191→      deviceId: params.deviceId,
   192→      baseUrl: params.homeserverUrl,
   193→    });
   194→
   195→    // Create a fresh client instance and configure it with the session + sliding sync
   196→    await this.initialize(params.homeserverUrl);
   197→
   198→    if (!this.instance) throw new Error("Failed to initialize client");
   199→
   200→    // Use local variable to help TypeScript with type narrowing
   201→    const client: ClientInterface = this.instance;
   202→
   203→    await client.restoreSession({
   204→      accessToken: params.accessToken,
   205→      refreshToken: params.refreshToken,
   206→      userId: params.userId,
   207→      deviceId: params.deviceId,
   208→      homeserverUrl: params.homeserverUrl,
   209→      oidcData: undefined,
   210→      slidingSyncVersion: SlidingSyncVersion.Native,
   211→    });
   212→
   213→    // Verify the session is valid by making a server request
   214→    // Use the params.userId since client.userId() might not be populated yet
   215→    try {
   216→      this.profile = await client.getProfile(params.userId);
   217→    } catch (error) {
   218→      console.warn("Session validation failed:", error);
   219→      throw new Error("Session is invalid or expired");
   220→    }
   221→
   222→    this.syncService = await client.syncService().finish();
   223→
   224→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   225→
   226→    await this.syncService.start();
   227→    await client.encryption().waitForE2eeInitializationTasks();
   228→
   229→    // Check if we need to bootstrap cross-signing or enable backups
   230→    try {
   231→      const encryption = client.encryption();
   232→      const backupExists = await encryption.backupExistsOnServer();
   233→      console.log("Backup exists on server:", backupExists);
   234→      console.log(
   235→        "Current verification state:",
   236→        encryption.verificationState(),
   237→      );
   238→
   239→      // If no backup exists and we're the only device, we might need to set one up
   240→      const isLastDevice = await encryption.isLastDevice();
   241→      console.log("Is last device:", isLastDevice);
   242→
   243→      if (!backupExists) {
   244→        console.log("Enabling backups for cross-signing...");
   245→        await encryption.enableBackups();
   246→      }
   247→
   248→      // Update atoms so providers can react to the initialized service
   249→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   250→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   251→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   252→    } catch (error) {
   253→      console.warn("Failed to check backup/verification status:", error);
   254→    }
   255→  };
