   311→  /** Manually refresh the room list and update the atom */
   312→  public static refreshRoomList = async () => {
   313→    if (!this.instance) return;
   314→
   315→    try {
   316→      const roomsArray = this.getRooms();
   317→
   318→      const sortedRooms = await Promise.all(
   319→        roomsArray.map(async (room) => ({
   320→          room,
   321→          timestamp: (await room.latestEvent())?.timestamp || 0,
   322→        })),
   323→      );
   324→
   325→      const filteredAndSortedRooms = sortedRooms
   326→        .filter(({ room }) => {
   327→          const membership = room.membership();
   328→
   329→          return (
   330→            membership !== Membership.Banned &&
   331→            membership !== Membership.Left &&
   332→            membership !== Membership.Knocked
   333→          );
   334→        })
   335→        .sort((a, b) => {
   336→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   337→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   338→          if (aInvited !== bInvited) return bInvited - aInvited;
   339→
   340→          return Number(b.timestamp) - Number(a.timestamp);
   341→        });
   342→
   343→      MatrixJotaiStore.set(
   344→        MatrixAtoms.roomList,
   345→        filteredAndSortedRooms.map(({ room }) => room),
   346→      );
   347→    } catch (error) {
   348→      console.error("Failed to refresh room list:", error);
   349→    }
   350→  };
