  public static leaveRoom = async (roomId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    await room.leave();
    const updatedRoom = this.instance.getRoom(roomId);
    if (!updatedRoom) throw new Error("Room not found");
    await updatedRoom.forget();
    // Manually refresh the room list to update UI immediately
    await this.refreshRoomList();
  };

  //VERIFICATION AND ENCRYPTION METHODS

  /** Get the current device verification state */
  public static getVerificationState = () => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.encryption().verificationState();
  };

  /** Check if the current device is verified */
  public static isDeviceVerified = () => {
    if (!this.instance) return false;
    const state = this.instance.encryption().verificationState();
    return state === VerificationState.Verified;
  };

  /** Get the device ID of the current session */
  public static getDeviceId = () => {
    if (!this.instance) return null;
    const session = this.instance.session();
    return session?.deviceId || null;
  };

  /** Get verification details about the current user */
  public static getVerificationDetails = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    const userId = this.instance.userId();
    if (!userId) throw new Error("User ID not found");

    const encryption = this.instance.encryption();
    const userIdentity = await encryption.userIdentity(userId);

    return {
      verificationState: encryption.verificationState(),
      isVerified: this.isDeviceVerified(),
      deviceId: this.getDeviceId(),
      userIdentity: userIdentity
        ? {
            isVerified: userIdentity.isVerified(),
            hasVerificationViolation: userIdentity.hasVerificationViolation(),
            masterKey: userIdentity.masterKey(),
          }
        : null,
    };
  };

  /** Enable backups for cross-signing (helps with device verification) */
  public static enableBackups = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    const encryption = this.instance.encryption();
    await encryption.enableBackups();
  };

  /** Check if a backup exists on the server */
  public static backupExists = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    return await this.instance.encryption().backupExistsOnServer();
  };

  /** Set up verification listeners - call this after login to enable verification */
  public static setupVerification = async (
    onRequest: VerificationRequestCallback,
    onEmojis: VerificationEmojisCallback,
    onStateChange: VerificationStateChangeCallback,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");

    // Store callbacks
    this.onVerificationRequest = onRequest;
    this.onVerificationEmojis = onEmojis;
    this.onVerificationStateChange = onStateChange;

    // Get verification controller
    this.verificationController =
      await this.instance.getSessionVerificationController();

    // Create delegate to handle verification events
    const delegate: SessionVerificationControllerDelegate = {
      didReceiveVerificationRequest: (
        details: SessionVerificationRequestDetails,
      ) => {
        console.log("📩 Verification request received:", details);
        this.onVerificationStateChange?.("request");
        this.onVerificationRequest?.(details);
      },

      didAcceptVerificationRequest: () => {
        console.log("✅ Verification request accepted");
      },

      didStartSasVerification: () => {
        console.log("🔐 SAS verification started");
      },

      didReceiveVerificationData: (data: SessionVerificationData) => {
        console.log("📊 Verification data received:", data);

        if (data.tag === SessionVerificationData_Tags.Emojis) {
          const emojis = data.inner.emojis.map((emoji) => ({
            symbol: emoji.symbol(),
            description: emoji.description(),
          }));
          console.log("🎭 Emojis:", emojis);
          this.onVerificationStateChange?.("emojis");
          this.onVerificationEmojis?.(emojis);
        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
          console.log("🔢 Decimals:", data.inner.values);
          // You could also handle decimal verification if needed
        }
      },

      didFail: () => {
        console.log("❌ Verification failed");
        this.onVerificationStateChange?.("failed");
      },

      didCancel: () => {
        console.log("🚫 Verification cancelled");
        this.onVerificationStateChange?.("cancelled");
      },

      didFinish: () => {
        console.log("🎉 Verification finished successfully!");
        this.onVerificationStateChange?.("success");
      },
    };

    // Set the delegate
    this.verificationController.setDelegate(delegate);
    console.log("✅ Verification controller set up successfully");
  };

  /** Acknowledge a verification request (call this when user taps on the verification notification) */
  public static acknowledgeVerification = async (
    senderId: string,
    flowId: string,
  ) => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.acknowledgeVerificationRequest(
      senderId,
      flowId,
    );
    console.log("✅ Verification request acknowledged");
  };

  /** Accept the verification request and start SAS verification */
  public static acceptVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.acceptVerificationRequest();
    await this.verificationController.startSasVerification();
    console.log("✅ Verification accepted and SAS started");
  };

  /** Approve the verification after comparing emojis */
  public static approveVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.approveVerification();
    console.log("✅ Verification approved");
  };

  /** Decline the verification if emojis don't match */
  public static declineVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.declineVerification();
    console.log("❌ Verification declined");
  };

  /** Cancel the verification flow */
  public static cancelVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.cancelVerification();
    console.log("🚫 Verification cancelled");
  };

  /** Start the verification flow */
  public static startVerification = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.startSasVerification();
    console.log("✅ Verification started");
  };

  /** Verify other user */
  public static verifyOtherUser = async (userId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.requestUserVerification(userId);
    console.log("✅ Verification requested");
  };

  /** Check if another user is verified by you */
  public static isUserVerified = async (userId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    try {
      const encryption = this.instance.encryption();
      const userIdentity = await encryption.userIdentity(userId);
      return !!userIdentity?.isVerified();
    } catch (error) {
      console.error("Failed to check user verification status:", error);
      return false;
    }
  };

  /** Get the current recovery state */
  public static getRecoveryState = () => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.encryption().recoveryState();
  };

  /** Check if recovery is enabled */
  public static isRecoveryEnabled = () => {
    if (!this.instance) return false;
    const state = this.instance.encryption().recoveryState();

    return state === RecoveryState.Enabled;
  };

  /** Enable recovery and get the recovery key
   * This will create a backup and return the recovery key that you MUST save */
  public static enableRecovery = async (passphrase?: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();

    // Create a progress listener
    const progressListener: EnableRecoveryProgressListener = {
      onUpdate: (status) => {
        console.log("🔐 Recovery progress:", status);
      },
    };

    // Enable recovery and get the key
    const recoveryKey = await encryption.enableRecovery(
      true, // waitForBackupsToUpload
      passphrase,
      progressListener,
    );

    console.log("✅ Recovery enabled! Save your recovery key securely.");
    return recoveryKey;
  };

  /** Reset the recovery key and get a new one
   * Use this if you lost your old recovery key*/
  public static resetRecoveryKey = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    const newRecoveryKey = await encryption.resetRecoveryKey();

    console.log("✅ Recovery key reset! Save your new recovery key securely.");
    return newRecoveryKey;
  };

  /** Recover using a recovery key
   * Use this to restore access to encrypted message */
  public static recoverWithKey = async (recoveryKey: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    await encryption.recover(recoveryKey);

    console.log("✅ Successfully recovered using recovery key!");
  };

  /** Disable recovery (removes backup and recovery key)
   * Warning: This will prevent you from recovering encrypted messages */
  public static disableRecovery = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    await encryption.disableRecovery();

    console.log("⚠️ Recovery disabled");
  };

  public static resetIdentity = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    await this.instance.encryption().resetIdentity();
    console.log("✅ Identity reset successfully");
  };

  // PUSH NOTIFICATIONS METHODS

  /** Get all pushers registered for this user */
  public static getPushers = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_GET}`,
        {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
        },
      );

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Failed to get pushers: ${response.status} - ${errorText}`,
        );
      }

      const data = await response.json();
      return data.pushers || [];
    } catch (error) {
      console.error("Failed to get pushers:", error);
      throw error;
    }
  };

  /** Check if a pusher is already registered for this device */
  public static isPusherRegistered = async (pushToken: string) => {
    try {
      const pushers = await this.getPushers();
      if (!this.instance) throw new Error("Client not initialized");
      const session = this.instance.session();
      if (!session) throw new Error("No active session");

      return pushers.some(
        (pusher: {
          pushkey: string;
          app_id: string;
          device_display_name: string;
        }) =>
          pusher.pushkey === pushToken &&
          pusher.app_id === APP_ID &&
          pusher.device_display_name === session.deviceId,
      );
    } catch (error) {
      console.error("Failed to check pusher registration:", error);
      return false;
    }
  };

  /** Register a pusher with the homeserver for push notifications */
  public static setPusher = async (pushToken: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    const pusherData = {
      pushkey: pushToken,
      kind: "http",
      app_id: APP_ID,
      app_display_name: "Cloak",
      device_display_name: session.deviceId || "Mobile Device",
      profile_tag: "", // Optional: for multiple pushers per device
      lang: "en",
      data: {
        url: `${SygnalURL}/${MATRIX_ENDPOINTS.PUSH_GATEWAY_URL}`,
      },
    };

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify(pusherData),
        },
      );

      if (!response.ok) {
        console.log("Failed to set pusher:", response);
        const errorText = await response.text();
        throw new Error(
          `Failed to set pusher: ${response.status} - ${errorText}`,
        );
      }

      return true;
    } catch (error) {
      console.error("Failed to register pusher:", error);
      throw error;
    }
  };

  /** Remove a pusher from the homeserver */
  public static removePusher = async (pushToken: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    const pusherData = {
      pushkey: pushToken,
      kind: null, // Setting kind to null removes the pusher
      app_id: APP_ID,
    };

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify(pusherData),
        },
      );

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Failed to remove pusher: ${response.status} - ${errorText}`,
        );
      }

      console.log("Pusher removed successfully from homeserver");
      return true;
    } catch (error) {
      console.error("Failed to remove pusher:", error);
      throw error;
    }
  };
}

