import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue } from "jotai";
import { MatrixService } from "modules/matrix-client/services";
import { StorageAtoms } from "modules/storage/jotai/atoms";
import { useState } from "react";
import {
  Alert,
  Image,
  type ImageSourcePropType,
  StyleSheet,
} from "react-native";
import Toast from "react-native-toast-message";
import { Button, GoBackHeader, Loading, ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { SettingsListItem, UserInfoItem } from "./fragments";

type SettingsRouteName =
  | "notifications"
  | "screenLock"
  | "encryption"
  | "about"
  | "reportProblem";

const ITEMS: {
  title: string;
  icon: ImageSourcePropType;
  routeName: SettingsRouteName;
}[] = [
  {
    title: "Notifications",
    icon: require("assets/icons/bell.png"),
    routeName: "notifications",
  },
  {
    title: "Screen Lock",
    icon: require("assets/icons/lock-key.png"),
    routeName: "screenLock",
  },
  {
    title: "Encryption",
    icon: require("assets/icons/key.png"),
    routeName: "encryption",
  },
  {
    title: "About",
    icon: require("assets/icons/info.png"),
    routeName: "about",
  },
];

export const Settings: React.FC<NativeStackScreenProps<Routes, "settings">> = ({
  navigation,
}) => {
  const [isSigningOut, setIsSigningOut] = useState(false);
  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);

  const signOut = async () => {
    try {
      setIsSigningOut(true);
      await MatrixService.logout();
      navigation.reset({
        index: 1,
        routes: [{ name: "welcome" }, { name: "login" }],
      });
      Toast.show({
        type: "success",
        text1: "Successfully signed out",
      });
    } catch (error) {
      console.error("Failed to logout: ", error);
      Toast.show({
        type: "error",
        text1: "Failed to sign out",
      });
    } finally {
      setIsSigningOut(false);
    }
  };

  const handleSignOut = () => {
    Alert.alert("Sign Out", "Are you sure you want to sign out?", [
      { text: "Cancel", style: "cancel" },
      { text: "Sign Out", style: "destructive", onPress: signOut },
    ]);
  };

  const handleOnPress = (routeName: SettingsRouteName) => {
    if (routeName === "screenLock") {
      if (screenLockPin) {
        navigation.navigate("verifyPin", { isSettingsScreen: true });
      } else navigation.navigate("setupScreenLock");

      return;
    }
    navigation.navigate(routeName);
  };

  return (
    <ScreenLayout>
      {isSigningOut ? <Loading text="Signing out..." /> : null}
      <Block align="center" gap={40}>
        <GoBackHeader title="Settings" margins={0} />
        <UserInfoItem />
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
        >
          {ITEMS.slice(0, 3).map((item, index, array) => (
            <SettingsListItem
              key={item.title}
              title={item.title}
              icon={item.icon}
              onPress={() => handleOnPress(item.routeName)}
              showSeparator={index !== array.length - 1}
            />
          ))}
        </Block>
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
        >
          {ITEMS.slice(3).map((item, index, array) => (
            <SettingsListItem
              key={item.title}
              title={item.title}
              icon={item.icon}
              onPress={() => handleOnPress(item.routeName)}
              showSeparator={index !== array.length - 1}
            />
          ))}
        </Block>
        <Button.Wrapper onPress={handleSignOut} style={styles.signOut}>
          <Block
            flexDirection="row"
            align="center"
            gap={12}
            paddings={[20, 12]}
            width="100%"
            background={Colors.white5}
            border={{ borderRadius: 16 }}
          >
            <Image
              source={require("assets/icons/sign-out.png")}
              width={24}
              height={24}
              tintColor={Colors.warning}
            />
            <Text size={TextSize.base} color={Colors.warning}>
              Sign Out
            </Text>
          </Block>
        </Button.Wrapper>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  signOut: {
    width: "100%",
  },
});

